  /** Flat emissive spill laid on the course; the collider height stays invisible. */
  private buildHazard(obstacle: ObstacleDescriptor, hole: Hole): THREE.Mesh {
    const key = 'hazard:' + obstacle.type;
    const mesh = new THREE.Mesh(
      this.boxGeometry,
      this.sensorMaterialFor(key, OBSTACLE_COLORS[obstacle.type], HAZARD_OPACITY, false),
    );
    mesh.name = obstacle.id;
    const size = scaledSize(obstacle);
    const position = obstacle.transform.position;
    const top = hazardSurfaceTop(hole, obstacle);
    mesh.position.set(position.x, top + HAZARD_SLAB_LIFT + HAZARD_SLAB_HEIGHT / 2, position.z);
    const rotation = obstacle.transform.rotation;
    if (rotation) {
      mesh.quaternion.set(rotation.x, rotation.y, rotation.z, rotation.w);
    }
    mesh.scale.set(size.x, HAZARD_SLAB_HEIGHT, size.z);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.visible = obstacle.enabled !== false;
    return mesh;
  }

  /** Force fields keep their volume so the reach stays readable, but stay a see-through haze. */
  private buildField(obstacle: ObstacleDescriptor): THREE.Mesh {
    const key = 'field:' + obstacle.type;
    const mesh = new THREE.Mesh(
      this.boxGeometry,
      this.sensorMaterialFor(key, OBSTACLE_COLORS[obstacle.type], FIELD_OPACITY, true),
    );
    mesh.name = obstacle.id;
    applyTransform(mesh, obstacle.transform, obstacle.size);
    mesh.castShadow = false;
    mesh.receiveShadow = false;
    mesh.visible = obstacle.enabled !== false;
    return mesh;
  }

